import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"FR 3.7.18 — Remove Collaborator Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-18-remove-collaborator-profile/spec.md","filePath":"feature/srs/06-ai-features/3-7-18-remove-collaborator-profile/spec.md"}'),i={name:"feature/srs/06-ai-features/3-7-18-remove-collaborator-profile/spec.md"};function c(d,e,l,n,s,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-18-—-remove-collaborator-profile" tabindex="-1">FR 3.7.18 — Remove Collaborator Profile <a class="header-anchor" href="#fr-3-7-18-—-remove-collaborator-profile" aria-label="Permalink to &quot;FR 3.7.18 — Remove Collaborator Profile&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.18</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-105</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Remove Collaborator Profile (Hard Delete Unused vs Safe Deactivate Used)</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-51</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>partner-directory</code> DA-949 / DA-950)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Safely retire Collaborator Profiles from an Agency Directory (<code>third_party_collaborators</code>) without ever corrupting historical or active Campaign records (<code>campaign_collaborators</code>, <code>BR-51</code>). Enforces a strict two-path lifecycle verified by PostgreSQL row locks, durable <code>first_used_at</code> + <code>usage_history_verified</code> markers, and <code>ON DELETE RESTRICT</code> foreign keys:</p><ul><li><strong>Hard Delete (<code>DELETE</code>):</strong> Allowed <strong>only</strong> when <code>usage_history_verified = true</code>, <code>first_used_at IS NULL</code>, and <code>0</code> rows reference the partner in <code>campaign_collaborators</code>.</li><li><strong>Safe Deactivate (<code>POST /{id}/deactivate</code>):</strong> Required for any partner that has ever been linked to a Campaign (<code>first_used_at IS NOT NULL</code>, active links exist, or legacy <code>usage_history_verified = false</code>), setting <code>is_active = false</code> to block future Campaign assignments while preserving all existing Campaign history.</li></ul><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code> (or authorized <code>Manager</code>), I want unused mistake entries to be cleanly deleted while any collaborator with Campaign history is safely deactivated (<code>isActive = false</code>) so that past Campaign deliverables and partner audit trails are never orphaned.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Strict Delete Eligibility Gate (<code>BR-51</code>):</strong><ul><li><code>DELETE /api/v1/agencies/{agencyId}/collaborators/{id}</code> acquires a pessimistic row lock on <code>third_party_collaborators</code> (in the same lock order as Campaign assign) and succeeds (<code>204 No Content</code>) <strong>only if</strong> <code>usage_history_verified = true AND first_used_at IS NULL AND NOT EXISTS (SELECT 1 FROM campaign_collaborators ...)</code>.</li><li>If the partner has <code>first_used_at IS NOT NULL</code> (even if the old Campaign/link was later removed), has existing links, or has <code>usage_history_verified = false</code> (unverified legacy baseline), <code>DELETE</code> returns <code>409 CONFLICT</code> with actionable error code instructing deactivation instead.</li></ul></li><li><strong>Idempotent Safe Deactivation (<code>POST /{id}/deactivate</code>):</strong><ul><li>Sets <code>is_active = false</code> and increments <code>version</code>. Repeated deactivate on an already inactive partner returns the current DTO idempotently.</li><li>Database trigger (<code>23514</code> check/trigger guard) and service layer block any new <code>campaign_collaborators</code> link creation to an inactive partner across both Workspace and legacy APIs, while existing Campaign links remain readable and updatable.</li></ul></li><li><strong>Race-Condition Safety:</strong> Concurrent <code>assign</code> vs <code>delete</code>/<code>deactivate</code> serializes on the <code>third_party_collaborators</code> row lock: if <code>assign</code> wins first, <code>first_used_at</code> is stamped and <code>delete</code> rejects with <code>409</code>; if <code>deactivate</code> wins first, <code>assign</code> rejects creating a new link.</li><li><strong>Distinct UI Confirmation Flows:</strong> <code>PartnerAction.tsx</code> renders &quot;Delete Permanently&quot; only when <code>canDelete == true</code>, and renders &quot;Deactivate Partner&quot; (with lock explanation tooltip when delete is locked) for used/legacy partners.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Distinct confirmation copy (<code>collaborators.confirm.delete.*</code> vs <code>collaborators.confirm.deactivate.*</code> and <code>collaborators.lockReason.*</code>) in <code>vi.json</code> and <code>en.json</code>.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Confirmation dialogs, warning callouts, and <code>Inactive</code> badges use semantic Light/Dark tokens with clear visual hierarchy.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Components:</strong> <code>pages/collaborators/components/PartnerAction.tsx</code>, <code>PartnerQuickActions.tsx</code>, <code>PartnerDetails.tsx</code>.</li><li><strong>Mobile Screen:</strong> <code>src/screens/agency/AgencyCollaboratorsScreen.tsx</code> destructive/deactivate action sheet.</li><li><strong>UI States:</strong><ul><li><strong>Unused Partner (<code>canDelete = true</code>):</strong> Offers both Deactivate and Delete Permanently with red destructive confirmation dialog.</li><li><strong>Used / Legacy Partner (<code>canDelete = false</code>):</strong> Delete action disabled/hidden with localized explanation (<code>firstUsedAt</code> or legacy unverified history); Deactivate button prominent.</li><li><strong>Inactive Partner (<code>isActive = false</code>):</strong> Displays <code>Inactive</code> badge; excluded from Workspace <code>PartnerPicker.tsx</code>.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Handler</th><th style="text-align:left;">Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>DELETE /api/v1/agencies/{agencyId}/collaborators/{id}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>DirectoryPartnerController.delete()</code></td><td style="text-align:left;"><code>204 No Content</code> (or <code>409 CONFLICT</code> when used/legacy)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/agencies/{agencyId}/collaborators/{id}/deactivate</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>DirectoryPartnerController.deactivate()</code></td><td style="text-align:left;"><code>200 ApiResponse&lt;DirectoryPartnerResponse&gt;</code> (<code>isActive = false</code>)</td></tr><tr><td style="text-align:left;"><code>DELETE /api/v1/collaborators/{collaboratorId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CollaboratorController.delete()</code></td><td style="text-align:left;">Enforces identical FK/usage guard</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>PARTNER_IN_USE_OR_HISTORICAL</code> (<code>409</code>, <code>MSG03</code>): Partner has current links, non-null <code>first_used_at</code>, or <code>usage_history_verified = false</code>.</li><li><code>VERSION_CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Concurrent modification mismatched <code>expectedVersion</code>.</li><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Cross-Agency or unauthorized role attempt.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-15-view-collaborator-directory/spec.html">FR 3.7.15 — View Collaborator Directory</a> · <a href="./../3-7-16-create-collaborator-profile/spec.html">FR 3.7.16 — Create Collaborator Profile</a> · <a href="./../3-7-17-update-collaborator-profile/spec.html">FR 3.7.17 — Update Collaborator Profile</a> · <a href="./../3-7-19-recommend-collaborator/spec.html">FR 3.7.19 — Recommend Collaborator</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via PostgreSQL 17 isolated concurrency &amp; trigger tests (<code>DirectoryPartnerPostgresTest</code>, <code>PartnerLifecycleMigrationTest</code> — <code>71 passed</code>), MockMvc <code>204/403/409</code> checks, <code>vi</code>/<code>en</code> i18n, and Light/Dark UI (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> Cascading deletion of Campaign collaboration history (strictly prohibited by <code>BR-51</code>).</li></ul>',20)])])}const u=t(i,[["render",c]]);export{h as __pageData,u as default};
